import numpy as np

def load_gsl():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except Exception as e:
        print(f"Error loading GSL libraries: {e}")
        raise

def process_array(input_list):
    try:
        input_array = (ctypes.c_double * len(input_list))()
        for i in range(len(input_list)):
            input_array[i] = ctypes.c_double(input_list[i]).value

        # Assuming the C function is declared as:
        # double process_array(double *input_array, size_t n);
        # and is in libgsl.so
        gsl = load_gsl()
        result = gsl.process_array(input_array, ctypes.c_size_t(len(input_list)))

        # Convert the result to a list of doubles
        output_list = [result[i] for i in range(len(input_list))]
        return output_list
    except Exception as e:
        print(f"Error processing array: {e}")
        return []

