            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
            cls._vector_type = cls._lib.gsl_vector
            cls._vector_type.argtypes = [ctypes.c_size_t, ctypes.POINTER(ctypes.c_double)]
            cls._vector_type.restype = ctypes.POINTER(cls._vector_type)

    @classmethod
    def create_gsl_vector(cls, data):
        if not cls._lib:
            cls.init_lib()
        size = len(data)
        ptr = cls._lib.gsl_vector_malloc(size)
        if not ptr:
            raise RuntimeError("Failed to allocate GSL vector")
        for i in range(size):
            cls._lib.gsl_vector_set(ptr, i, data[i])
        return ptr

    @classmethod
    def get_data(cls, vec):
        if not cls._lib:
            cls.init_lib()
        size = cls._lib.gsl_vector_size(vec)
        data = (ctypes.c_double * size)()
        cls._lib.gsl_vector_get(vec, data, 0, size-1)
        return [data[i] for i in range(size)]

