    gsl = GSLVector()
    src = gsl.create_gsl_vector(data)
    dst = gsl.create_gsl_vector([0.0]*size)

    gsl._lib.gsl_vector_memcpy(dst, src)

    result = gsl.get_data(dst)
    return result

