import sys

class GslSfResult:
    _lib = None

    @classmethod
    def load_libs(cls):
        if cls._lib is None:
            try:
                ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
                cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
            except Exception as e:
                print(f"Error loading GSL libraries: {e}")
                sys.exit(1)

    @classmethod
    def compute_synchrotron(cls, x):
        cls.load_libs()
        gsl = cls._lib
        synchrotron_1 = gsl.gsl_sf_synchrotron_1
        synchrotron_2 = gsl.gsl_sf_synchrotron_2
        synchrotron_1.argtypes = [ctypes.c_double]
        synchrotron_1.restype = ctypes.c_double
        synchrotron_2.argtypes = [ctypes.c_double]
        synchrotron_2.restype = ctypes.c_double
        try:
            res1 = synchrotron_1(x)
            res2 = synchrotron_2(x)
            return (res1, res2)
        except Exception as e:
            print(f"Error computing synchrotron functions: {e}")
            return (0.0, 0.0)

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
