class gsl_complex:
    _type = ctypes.c_double * 2

    def __init__(self, real, imag):
        self._data = gsl_complex._type()
        self._data[0] = real
        self._data[1] = imag

    @property
def real(self):
    return self._data[0]

    @property
def imag(self):
    return self._data[1]

    def __add__(self, other):
        if not isinstance(other, gsl_complex):
            raise TypeError("Can only add gsl_complex instances")
        return gsl_complex_add(self, other)

    def __repr__(self):
        return f"gsl_complex({self.real}, {self.imag})"

def load_gsl_libraries():
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    return gsl

def gsl_complex_add(gsl, z1, z2):
    result = gsl_complex()
    gsl.gsl_complex_add.argtypes = [ctypes.POINTER(gsl_complex._type), ctypes.POINTER(gsl_complex._type), ctypes.POINTER(gsl_complex._type)]
    gsl.gsl_complex_add.restype = ctypes.POINTER(gsl_complex._type)
    result_ptr = gsl.gsl_complex_add(gsl, z1._data, z2._data)
    result._data = result_ptr.contents
    return result

