import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)

    def to_gsl(self):
        gsl_matrix = ctypes.create_string_buffer(ctypes.c_size_t(self.size * self.size).value * ctypes.sizeof(ctypes.c_double))
        ptr = ctypes.pointer(gsl_matrix)
        for i in range(self.size):
            for j in range(self.size):
                ctypes.memmove(ctypes.addressof(ptr.contents.data[i * self.size + j]), 
                               ctypes.c_double(self.data[i][j]).value,
                               ctypes.c_size_t(ctypes.sizeof(ctypes.c_double)).value)
        return gsl_matrix

    def from_gsl(self, gsl_matrix):
        self.data = [[0.0 for _ in range(self.size)] for _ in range(self.size)]
        for i in range(self.size):
            for j in range(self.size):
                self.data[i][j] = ctypes.c_double(ctypes.addressof(gsl_matrix.contents.data[i * self.size + j])).value

    def __str__(self):
        return '\n'.join(' '.join(map(str, row)) for row in self.data)

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix).to_gsl()

def gsl_matrix_to_numpy(gsl_matrix):
    matrix = [[0.0 for _ in range(gsl_matrix.size)] for _ in range(gsl_matrix.size)]
    for i in range(gsl_matrix.size):
        for j in range(gsl_matrix.size):
            matrix[i][j] = ctypes.c_double(ctypes.addressof(gsl_matrix.contents.data[i * gsl_matrix.size + j])).value
    return matrix

def compute_matrix_exponential(matrix, mode):
    if not isinstance(matrix, list):
        raise ValueError("Input must be a list")
    size = len(matrix)
    if any(len(row) != size for row in matrix):
        raise ValueError("Matrix must be square")

    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

    gsl_matrix = matrix_to_gsl(matrix)
    gsl_matrix_exp = ctypes.create_string_buffer(ctypes.c_size_t(size * size).value * ctypes.sizeof(ctypes.c_double))
    gsl.gsl_linalg_exponential_ss(ctypes.pointer(gsl_matrix), ctypes.pointer(gsl_matrix_exp), ctypes.c_int(mode))

    result = gsl_matrix_to_numpy(ctypes.pointer(gsl_matrix_exp))
    return result

