import numpy as np

class GSLMatrix:
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _lib2 = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    _lib.list_to_gsl_matrix.argtypes = [ctypes.POINTER(ctypes.c_complex)]
    _lib.list_to_gsl_matrix.restype = ctypes.POINTER(ctypes.c_void_p)

    _lib.add_matrices.argtypes = [ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_void_p)]
    _lib.add_matrices.restype = ctypes.POINTER(ctypes.c_void_p)

    def __init__(self, data):
        self.data = data
        self.matrix = self._lib.list_to_gsl_matrix(ctypes.pointer(ctypes.c_complex(*np.ravel(self.data))))

    def __add__(self, other):
        if not (self.matrix and other.matrix):
            raise ValueError("Matrices must be initialized")
        if self.shape != other.shape:
            raise ValueError("Matrices must have the same dimensions")
        result = self._lib.add_matrices(self.matrix, other.matrix)
        return GSLMatrix(result)

    @property
    def shape(self):
        return (len(self.data), len(self.data[0]))

    def to_list(self):
        data = np.zeros(len(self.data)*len(self.data[0]), dtype=np.complex_)
        for i in range(len(self.data)):
            for j in range(len(self.data[i])):
                data[i*len(self.data[i]) + j] = ctypes.c_complex.from_address(self.matrix.contents.data + i*len(self.data[i]) + j).value
        return [data[i*len(self.data[i]) : (i+1)*len(self.data[i])].tolist() for i in range(len(self.data))]

