    # Load the required GSL libraries
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        print(f"Error loading GSL libraries: {e}")
        return None

    # Convert Python list to C double array
    c_data = (ctypes.c_double * len(data))(*data)

    # Define the C function signature
    gsl.C gsl_init = gsl.c_function('gsl_block_init', [])

    # Call the C function
    try:
        gsl_init(c_data)
        return ctypes.pointer(c_data)
    except Exception as e:
        print(f"Error initializing GSL block: {e}")
        return None

